package com.southstand.football.detail;
import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.baomidou.mybatisplus.core.conditions.Wrapper;import java.util.List;import org.junit.jupiter.api.Test;
class PlayerCareerServiceTests{@Test void careerAggregatesT15Stats(){var f=new FootballDetailTestFixture();var v=f.service.playerCareer(f.PLAYER);assertThat(v.totalAppearances()).isEqualTo(20);assertThat(v.totalGoals()).isEqualTo(10);assertThat(v.teamCount()).isEqualTo(1);}@Test void emptyCareerReturnsZeros(){var f=new FootballDetailTestFixture();when(f.playerStats.selectList(any(Wrapper.class))).thenReturn(List.of());var v=f.service.playerCareer(f.PLAYER);assertThat(v.totalGoals()).isZero();assertThat(v.bySeason()).isEmpty();}}
